def _parse_tree(s, pos):
    # s[pos] == "("
    pos += 1
    if pos >= len(s) or s[pos] != ";":
        raise ValueError("tree with no nodes")
    nodes = []
    while pos < len(s) and s[pos] == ";":
        props, pos = _parse_node(s, pos + 1)
        nodes.append(props)
    children = []
    while pos < len(s) and s[pos] == "(":
        child, pos = _parse_tree(s, pos)
        children.append(child)
    if pos >= len(s) or s[pos] != ")":
        raise ValueError("tree missing")
    pos += 1
    # chain nodes: last node gets the variations as children
    tree = SgfTree(nodes[-1], children)
    for props in reversed(nodes[:-1]):
        tree = SgfTree(props, [tree])
    return tree, pos


def _parse_node(s, pos):
    props = {}
    while pos < len(s) and s[pos] not in ";()":
        start = pos
        while pos < len(s) and s[pos] != "[":
            pos += 1
        key = s[start:pos]
        if pos >= len(s) or not key:
            raise ValueError("properties without delimiter")
        if not key.isalpha() or not key.isupper():
            raise ValueError("property must be in uppercase")
        values = []
        while pos < len(s) and s[pos] == "[":
            pos += 1
            out = []
            while True:
                if pos >= len(s):
                    raise ValueError("properties without delimiter")
                c = s[pos]
                if c == "]":
                    pos += 1
                    break
                if c == "\\":
                    pos += 1
                    if pos >= len(s):
                        raise ValueError("properties without delimiter")
                    c = s[pos]
                    if c != "\n":
                        out.append(" " if c.isspace() else c)
                elif c != "\n" and c.isspace():
                    out.append(" ")
                else:
                    out.append(c)
                pos += 1
            values.append("".join(out))
        props.setdefault(key, []).extend(values)
    return props, pos"}

